var calc_output = [];

var sex = parseFloat(sex);
var age = parseFloat(age);
var diabetes = parseFloat(diabetes);
var smoking = parseFloat(smoking);
var sbp = parseFloat(sbp);

if (UOMSYSTEM == true) {
    var tc = parseFloat(tc)*0.02586;
    var hdl = parseFloat(hdl)*0.02586;
} else if (UOMSYSTEM == false) {
    var tc = parseFloat(tc);
    var hdl = parseFloat(hdl);
}

var region = parseFloat(region);

var cage = age - 73;
var csbp = sbp - 150
var ctc = tc - 6;
var chdl = hdl - 1.4;
var diabetes_age = diabetes*cage;
var smoking_age = smoking*cage;
var sbp_age = csbp*cage;
var tc_age = ctc*cage;
var hdl_age = chdl*cage;

var x;
var risk_10;

if (sex == 0) {
    x = 0.0634*cage + 0.4245*diabetes + 0.3524*smoking + 0.0094*csbp + 0.085*ctc - 0.3564*chdl - 0.0174*diabetes_age - 0.0247*smoking_age - 0.0005*sbp_age + 0.0073*tc_age + 0.0091*hdl_age;
    risk_10 = 1 - Math.pow(0.7576, Math.exp(x - 0.0929));
} else {
    x = 0.0789*cage + 0.601*diabetes + 0.4921*smoking + 0.0102*csbp + 0.0605*ctc - 0.304*chdl - 0.0107*diabetes_age - 0.0255*smoking_age - 0.0004*sbp_age - 0.0009*tc_age + 0.0154*hdl_age;
    risk_10 = 1 - Math.pow(0.8082, Math.exp(x - 0.229));
}

var scale1;
var scale2;
if (region == 1) {
    if (sex == 0) {
        scale1 = -0.34;
        scale2 = 1.19;
    } else {
        scale1 = -0.52;
        scale2 = 1.01;
    }
} else if (region == 2) {
    if (sex == 0) {
        scale1 = 0.01;
        scale2 = 1.25;
    } else {
        scale1 = -0.10;
        scale2 = 1.10;
    }
} else if (region == 3) {
    if (sex == 0) {
        scale1 = 0.08;
        scale2 = 1.15;
    } else {
        scale1 = 0.38;
        scale2 = 1.09;
    }
} else if (region == 4) {
    if (sex == 0) {
        scale1 = 0.05;
        scale2 = 0.70;
    } else {
        scale1 = 0.38;
        scale2 = 0.69;
    }
}

var c_risk = [1 - Math.exp(-Math.exp(scale1 + scale2*Math.log(-Math.log(1 - risk_10))))]*100

calc_output.push({
    name: 'mini',
    value: c_risk.toFixed(1),
    value_text: '%',
    message: '10-year risk of CVD'
});  
calc_output.push({
    name: '10499_SCORE2-OP_result',
    value: c_risk.toFixed(1),
    value_text: '%',
    message: '10-year risk of CVD'
});
